export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  let thresholdsResult = [];
  let passed = true;

  if (thresholds && typeof thresholds === 'object') {
    const metricMap = new Map(evaluations.map((m) => [m.id, m]));

    thresholdsResult = Object.entries(thresholds).map(([metricId, min]) => {
      const metric = metricMap.get(metricId);
      const score = metric?.score;
      const metricPassed = score !== null && score !== undefined && score >= min;
      if (!metricPassed) passed = false;
      return {
        metric: metricId,
        min,
        score: score ?? null,
        passed: metricPassed
      };
    });
  }

  return {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations,
    passed,
    thresholds: thresholdsResult
  };
}

